import { addComposerChild$, realmPlugin } from '@mdxeditor/editor'
import { markdownPasteConfig$, type MarkdownPasteConfig } from './markdown_paste_cell'
import { MarkdownPastePlugin } from './markdown_paste_plugin'

/** Connects Markdown-aware clipboard handling to MDXEditor's Lexical editor. */
export const markdownPastePlugin = realmPlugin<MarkdownPasteConfig>({
    init(realm, params) {
        if (!params) throw new Error('Markdown paste plugin requires parameters')

        realm.register(markdownPasteConfig$)
        realm.pub(markdownPasteConfig$, params)
        realm.pub(addComposerChild$, MarkdownPastePlugin)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown paste plugin requires parameters')

        realm.pub(markdownPasteConfig$, params)
    },
})

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { useCellValue } from '@mdxeditor/editor'
import {
    $getSelection,
    $isRangeSelection,
    COMMAND_PRIORITY_HIGH,
    COPY_COMMAND,
    KEY_DOWN_COMMAND,
    PASTE_COMMAND,
    type PasteCommandType,
} from 'lexical'
import { useCallback, useEffect, useRef } from 'react'
import { dialogService } from '../../services/dialog_service'
import { useDialogError } from '../hooks/use_dialog_error'
import { markdownPasteConfig$ } from './markdown_paste_cell'

const MARKDOWN_MIME_TYPE = 'text/markdown'
const PLAIN_TEXT_MIME_TYPE = 'text/plain'

interface ShortcutIntent {
    generation: number
    shifted: boolean
}

function trackShortcutIntent(intent: ShortcutIntent, shifted: boolean) {
    intent.generation += 1
    intent.shifted = shifted
    const generation = intent.generation
    setTimeout(() => {
        if (intent.generation === generation) intent.shifted = false
    }, 0)
}

function consumeShiftedIntent(intent: ShortcutIntent) {
    const shifted = intent.shifted
    intent.shifted = false
    return shifted
}

function isControlShortcut(event: KeyboardEvent, key: string) {
    return event.ctrlKey && !event.altKey && !event.metaKey && event.key.toLowerCase() === key
}

/** Handles Markdown-aware and literal-text clipboard operations for MDXEditor. */
export function MarkdownPastePlugin() {
    const config = useCellValue(markdownPasteConfig$)
    const [editor] = useLexicalComposerContext()
    const copyIntentRef = useRef<ShortcutIntent>({ generation: 0, shifted: false })
    const pasteIntentRef = useRef<ShortcutIntent>({ generation: 0, shifted: false })
    const configError = config ? null : new Error('Cannot register Markdown paste without configuration')
    useDialogError(configError, 'Markdown paste is unavailable')

    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        if (isControlShortcut(event, 'c')) trackShortcutIntent(copyIntentRef.current, event.shiftKey)
        if (isControlShortcut(event, 'v')) trackShortcutIntent(pasteIntentRef.current, event.shiftKey)
        return false
    }, [])

    const handleCopy = useCallback((event: ClipboardEvent | KeyboardEvent | null) => {
        const shifted = consumeShiftedIntent(copyIntentRef.current)
        if (!config || !event || !('clipboardData' in event) || !event.clipboardData) return false

        const selection = $getSelection()
        if (!$isRangeSelection(selection) || selection.isCollapsed()) return false

        try {
            const plainText = selection.getTextContent()
            if (shifted) {
                event.clipboardData.setData(PLAIN_TEXT_MIME_TYPE, plainText)
            } else {
                const markdown = config.getSelectionMarkdown()
                if (!markdown) throw new Error('Selected content could not be serialized as Markdown')
                event.clipboardData.setData(MARKDOWN_MIME_TYPE, markdown)
                event.clipboardData.setData(PLAIN_TEXT_MIME_TYPE, markdown)
            }
            event.preventDefault()
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Selected content could not be copied' })
            return false
        }
    }, [config])

    const handlePaste = useCallback((event: PasteCommandType) => {
        const shifted = consumeShiftedIntent(pasteIntentRef.current)
        if (!config || config.readOnly || !('clipboardData' in event) || !event.clipboardData) return false

        try {
            if (shifted) {
                const plainText = event.clipboardData.getData(PLAIN_TEXT_MIME_TYPE)
                if (!plainText) return false
                const selection = $getSelection()
                if (!$isRangeSelection(selection)) return false
                selection.insertText(plainText)
                event.preventDefault()
                return true
            }

            const markdown = event.clipboardData.getData(MARKDOWN_MIME_TYPE)
                || event.clipboardData.getData(PLAIN_TEXT_MIME_TYPE)
            if (!markdown) return false

            config.insertMarkdown(markdown)
            event.preventDefault()
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Clipboard content could not be pasted' })
            return false
        }
    }, [config])

    useEffect(() => {
        const unregisterKeyDown = editor.registerCommand(KEY_DOWN_COMMAND, handleKeyDown, COMMAND_PRIORITY_HIGH)
        const unregisterCopy = editor.registerCommand(COPY_COMMAND, handleCopy, COMMAND_PRIORITY_HIGH)
        const unregisterPaste = editor.registerCommand(PASTE_COMMAND, handlePaste, COMMAND_PRIORITY_HIGH)

        return () => {
            unregisterKeyDown()
            unregisterCopy()
            unregisterPaste()
        }
    }, [editor, handleCopy, handleKeyDown, handlePaste])

    return null
}

import { Cell } from '@mdxeditor/editor'

export interface MarkdownPasteConfig {
    getSelectionMarkdown: () => string
    insertMarkdown: (markdown: string) => void
    readOnly: boolean
}

export const markdownPasteConfig$ = Cell<MarkdownPasteConfig | null>(null)

import { Box } from '@mui/material'
import {
    MDXEditor, codeBlockPlugin, codeMirrorPlugin, diffSourcePlugin,
    headingsPlugin, imagePlugin, linkDialogPlugin, linkPlugin, listsPlugin, markdownShortcutPlugin, quotePlugin,
    tablePlugin, thematicBreakPlugin, toolbarPlugin,
    type MDXEditorMethods, type ViewMode,
} from '@mdxeditor/editor'
import '@mdxeditor/editor/style.css'
import {
    forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef,
    type FocusEvent, type ReactNode,
} from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { useProjectState } from '../hooks/use_project_state'
import { dialogService } from '../../services/dialog_service'
import { useAppTheme } from '../../theme/use_app_theme'
import { markdownDocumentHistoryPlugin } from './markdown_document_history_realm_plugin'
import type { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import { MarkdownFormatToolbarControls } from './markdown_format_toolbar_controls'
import { markdownFileSearchPlugin } from './markdown_file_search_realm_plugin'
import { markdownLocalTextSearchPlugin } from './markdown_local_text_search_realm_plugin'
import { plainMarkdownPlugin } from './plain_markdown_realm_plugin'
import { markdownPlaceholderPlugin } from './markdown_placeholder_realm_plugin'
import { registerMarkdownEditorStage } from '../../services/project/markdown_editor_staging'
import { markdownPastePlugin } from './markdown_paste_realm_plugin'
import type {
    ActiveMarkdownDocumentChangedDetail,
    MarkdownBindingKind,
    MarkdownDataSource,
    MarkdownDocumentTarget,
} from './markdown_data_source'

const DEFAULT_CODE_LANGUAGE = ''
const CODE_BLOCK_LANGUAGES = { '': 'Plain text', js: 'JavaScript', ts: 'TypeScript', tsx: 'TSX', bash: 'Shell' }
const EMPTY_PLACEHOLDERS: readonly ActionPlaceholder[] = []
const EMPTY_REPOSITORY_FILES: readonly string[] = []

export interface MarkdownEditorHandle {
    flush(): boolean
    getMarkdown(): string
    setMarkdown(markdown: string): void
}

interface MarkdownEditorPresentationProps {
    diffMarkdown?: string
    flushOnBlur?: boolean
    /** Omit format toolbar entirely. */
    hideToolbar?: boolean
    /** Set false when containing surface owns Ctrl+F behavior. */
    localTextSearch?: boolean
    overlayContainer?: HTMLElement | null
    placeholders?: readonly ActionPlaceholder[]
    readOnly?: boolean
    toolbarContents?: () => ReactNode
    viewMode?: ViewMode
}

interface MarkdownEditorDataSourceProps extends MarkdownEditorPresentationProps {
    binding: MarkdownBindingKind
    dataSource: MarkdownDataSource
    historyStore: MarkdownDocumentHistoryStore
    markdown?: never
    onChange?: never
    onDirtyChange?: never
    onLiveChange?: never
}

interface MarkdownEditorLocalProps extends MarkdownEditorPresentationProps {
    binding?: never
    dataSource?: never
    historyStore?: never
    markdown: string
    onChange: (markdown: string) => void
    onDirtyChange?: (dirty: boolean) => void
    onLiveChange?: (markdown: string) => void
}

type MarkdownEditorProps = MarkdownEditorDataSourceProps | MarkdownEditorLocalProps

interface MarkdownDocumentSnapshot {
    target: MarkdownDocumentTarget | null
    markdown: string
}

interface MarkdownProcessingError {
    error: string
}

function initialDocument(props: MarkdownEditorProps): MarkdownDocumentSnapshot {
    if (!props.dataSource) return { target: null, markdown: props.markdown }

    const target = props.dataSource.getActiveTarget(props.binding)
    return { target, markdown: target ? props.dataSource.getMarkdown(target) : '' }
}

/** Reusable MDXEditor surface with local-buffer and persisted data-source modes. */
export const MarkdownEditor = forwardRef<MarkdownEditorHandle, MarkdownEditorProps>(function MarkdownEditor(props, ref) {
    const {
        flushOnBlur = false,
        diffMarkdown,
        hideToolbar = false,
        localTextSearch = true,
        overlayContainer,
        placeholders = EMPTY_PLACEHOLDERS,
        readOnly = false,
        toolbarContents: customToolbarContents,
        viewMode,
    } = props
    const dataSource = props.dataSource
    const binding = props.binding
    const historyStore = props.historyStore
    const { snapshot } = useProjectState()
    const repositoryFiles = snapshot?.repositoryFiles ?? EMPTY_REPOSITORY_FILES
    const initialDocumentRef = useRef<MarkdownDocumentSnapshot | null>(null)
    if (!initialDocumentRef.current) initialDocumentRef.current = initialDocument(props)
    const initialDocumentSnapshot = initialDocumentRef.current
    const { markdownContentSx, mode } = useAppTheme()
    const editorRef = useRef<MDXEditorMethods>(null)
    const activeTargetRef = useRef(initialDocumentSnapshot.target)
    const latestMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const lastEmittedMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const dirtyBaselineEstablishedRef = useRef(false)
    const missingEditorReportedRef = useRef(false)
    const replacingMarkdownRef = useRef(false)
    const onChangeRef = useRef(props.onChange)
    const onDirtyChangeRef = useRef(props.onDirtyChange)
    const onLiveChangeRef = useRef(props.onLiveChange)
    const applyPendingDocumentChangeRef = useRef<() => void>(() => undefined)
    onChangeRef.current = props.onChange
    onDirtyChangeRef.current = props.onDirtyChange
    onLiveChangeRef.current = props.onLiveChange

    const setDirty = useCallback((dirty: boolean) => {
        onDirtyChangeRef.current?.(dirty)
    }, [])

    const flush = useCallback(() => {
        if (latestMarkdownRef.current === lastEmittedMarkdownRef.current) return true

        const activeTarget = activeTargetRef.current
        if (dataSource && binding) {
            if (!activeTarget) return false
            const committed = dataSource.commit(binding, activeTarget, latestMarkdownRef.current)
            if (!committed) return false
        } else {
            onChangeRef.current?.(latestMarkdownRef.current)
        }
        lastEmittedMarkdownRef.current = latestMarkdownRef.current
        setDirty(false)
        queueMicrotask(() => applyPendingDocumentChangeRef.current())

        return true
    }, [binding, dataSource, setDirty])

    const prepareDocumentSwitch = useCallback((detail: ActiveMarkdownDocumentChangedDetail, nextMarkdown: string) => {
        if (detail.discard) lastEmittedMarkdownRef.current = latestMarkdownRef.current
        if (!flush()) return null

        const currentMarkdown = latestMarkdownRef.current
        activeTargetRef.current = detail.target
        latestMarkdownRef.current = nextMarkdown
        lastEmittedMarkdownRef.current = nextMarkdown
        setDirty(false)

        return currentMarkdown
    }, [flush, setDirty])

    const completeDocumentSwitch = useCallback((normalizedMarkdown: string) => {
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        setDirty(false)
    }, [setDirty])

    const getMarkdown = useCallback(() => editorRef.current?.getMarkdown() ?? latestMarkdownRef.current, [])
    const getTarget = useCallback(() => activeTargetRef.current, [])

    const replaceMarkdown = useCallback((markdown: string) => {
        replacingMarkdownRef.current = true
        editorRef.current?.setMarkdown(markdown)
        replacingMarkdownRef.current = false
    }, [])

    const setPendingDocumentChangeRetry = useCallback((retry: () => void) => {
        applyPendingDocumentChangeRef.current = retry
    }, [])

    const historyPluginConfig = useMemo(() => historyStore && binding && dataSource
        ? {
            binding,
            completeDocumentSwitch,
            dataSource,
            getTarget,
            getMarkdown,
            historyStore,
            prepareDocumentSwitch,
            replaceMarkdown,
            setPendingDocumentChangeRetry,
        }
        : null, [
        binding,
        completeDocumentSwitch,
        dataSource,
        getTarget,
        getMarkdown,
        historyStore,
        prepareDocumentSwitch,
        replaceMarkdown,
        setPendingDocumentChangeRetry,
    ])

    useEffect(() => {
        if (!editorRef.current) {
            if (!missingEditorReportedRef.current) {
                missingEditorReportedRef.current = true
                dialogService.error(new Error('Cannot baseline markdown before editor is mounted'), {fallbackMessage: 'Markdown editor could not be initialized'})
            }
            return
        }

        const normalizedMarkdown = editorRef.current.getMarkdown()
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        dirtyBaselineEstablishedRef.current = true
    }, [])

    useEffect(() => {
        const unregister = registerMarkdownEditorStage(flush)

        return () => {
            unregister()
            flush()
        }
    }, [flush])

    useImperativeHandle(ref, () => ({
        flush,
        getMarkdown: () => latestMarkdownRef.current,
        setMarkdown: (markdown: string) => {
            replaceMarkdown(markdown)
            latestMarkdownRef.current = markdown
            lastEmittedMarkdownRef.current = markdown
            setDirty(false)
        },
    }), [flush, replaceMarkdown, setDirty])

    const handleEditorChange = useCallback((markdown: string) => {
        if (replacingMarkdownRef.current || latestMarkdownRef.current === markdown) return

        latestMarkdownRef.current = markdown
        if (!dirtyBaselineEstablishedRef.current) return
        setDirty(markdown !== lastEmittedMarkdownRef.current)
        onLiveChangeRef.current?.(markdown)
        const activeTarget = activeTargetRef.current
        if (dataSource && binding && activeTarget) dataSource.edit(binding, activeTarget, markdown)
    }, [binding, dataSource, setDirty])

    const handleEditorError = useCallback(({ error }: MarkdownProcessingError) => {
        dialogService.error(new Error(error), { fallbackMessage: 'Markdown could not be parsed' })
    }, [])

    const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
        if (!flushOnBlur || event.currentTarget.contains(event.relatedTarget)) return
        flush()
    }

    const insertMarkdown = useCallback((markdown: string) => {
        editorRef.current?.insertMarkdown(markdown)
    }, [])

    const getSelectionMarkdown = useCallback(() => editorRef.current?.getSelectionMarkdown() ?? '', [])

    const defaultToolbarContents = useCallback(
        () => <MarkdownFormatToolbarControls overlayContainer={overlayContainer} placeholders={placeholders} />,
        [overlayContainer, placeholders],
    )
    const toolbarContents = customToolbarContents ?? defaultToolbarContents
    const editorSx = {
        ...markdownContentSx,
        '& .mdxeditor-toolbar': { bgcolor: 'background.paper', position: 'sticky', top: 0, zIndex: 1 },
    }
    const historyPlugin = historyPluginConfig ? markdownDocumentHistoryPlugin(historyPluginConfig) : null
    const plugins = [
        headingsPlugin(),
        listsPlugin(),
        quotePlugin(),
        thematicBreakPlugin(),
        linkPlugin(),
        linkDialogPlugin(),
        imagePlugin(),
        tablePlugin(),
        codeBlockPlugin({ defaultCodeBlockLanguage: DEFAULT_CODE_LANGUAGE }),
        codeMirrorPlugin({ codeBlockLanguages: CODE_BLOCK_LANGUAGES }),
        markdownShortcutPlugin(),
        plainMarkdownPlugin(),
        ...(viewMode ? [diffSourcePlugin({ diffMarkdown: diffMarkdown ?? '', viewMode })] : []),
        ...(hideToolbar ? [] : [toolbarPlugin({ toolbarContents })]),
        markdownPlaceholderPlugin({ overlayContainer, placeholders }),
        markdownFileSearchPlugin({ overlayContainer, repositoryFiles }),
        ...(localTextSearch ? [markdownLocalTextSearchPlugin({ overlayContainer })] : []),
        markdownPastePlugin({ getSelectionMarkdown, insertMarkdown, readOnly }),
        ...(historyPlugin ? [historyPlugin] : []),
    ]

    return (
        <Box data-sticky-toolbar onBlur={handleBlur} sx={editorSx}>
            <MDXEditor
                className={mode === 'dark' ? 'dark-theme' : 'light-theme'}
                contentEditableClassName="mdxeditor-content"
                markdown={initialDocumentSnapshot.markdown}
                onChange={handleEditorChange}
                onError={handleEditorError}
                overlayContainer={overlayContainer}
                plugins={plugins}
                readOnly={readOnly}
                ref={editorRef}
                suppressHtmlProcessing
                suppressSharedHistory={!!historyStore}
            />
        </Box>
    )
})

import type { ActionOpenDocument, CardOpenDocument, OpenDocument } from '../../services/open_files_service'

export type MarkdownBindingKind = 'board-card' | 'list-action' | 'list-card'

export type ActionMarkdownSection =
    | { kind: 'prompt' }
    | { kind: 'phrase', identity: string }

export type MarkdownDocumentTarget =
    | { document: ActionOpenDocument, section: ActionMarkdownSection }
    | { document: CardOpenDocument, section?: never }

export interface ActiveMarkdownDocumentChangedDetail {
    binding: MarkdownBindingKind
    /** Drop outgoing buffer because owning domain data was explicitly discarded. */
    discard?: boolean
    target: MarkdownDocumentTarget | null
}

export interface MarkdownReplacedDetail {
    originBinding: MarkdownBindingKind | null
    target: MarkdownDocumentTarget
}

export interface MarkdownBindingsSnapshot {
    activeBoardCardTarget: MarkdownDocumentTarget | null
    activeListActionTarget: MarkdownDocumentTarget | null
    activeListCardTarget: MarkdownDocumentTarget | null
}

export interface MarkdownDataSource extends EventTarget {
    commit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): boolean
    edit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): void
    getActiveTarget(binding: MarkdownBindingKind): MarkdownDocumentTarget | null
    getMarkdown(target: MarkdownDocumentTarget): string
}

const INITIAL_BINDINGS: MarkdownBindingsSnapshot = {
    activeBoardCardTarget: null,
    activeListActionTarget: null,
    activeListCardTarget: null,
}

function bindingSnapshotKey(binding: MarkdownBindingKind): keyof MarkdownBindingsSnapshot {
    if (binding === 'board-card') return 'activeBoardCardTarget'
    if (binding === 'list-card') return 'activeListCardTarget'

    return 'activeListActionTarget'
}

export function sameMarkdownTarget(first: MarkdownDocumentTarget | null, second: MarkdownDocumentTarget | null) {
    if (first?.document !== second?.document) return false
    if (!first || !second) return true
    if (!first.section && !second.section) return true
    if (!first.section || !second.section) return false
    if (first.section.kind !== second.section.kind) return false

    return first.section.kind === 'prompt'
        || (second.section.kind === 'phrase' && first.section.identity === second.section.identity)
}

export function markdownTargetDocument(target: MarkdownDocumentTarget): OpenDocument {
    return target.document
}

/** Shared active-target and event behavior for Markdown sources. */
export abstract class MarkdownDataSourceBase extends EventTarget implements MarkdownDataSource {
    private bindings = INITIAL_BINDINGS

    abstract commit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): boolean
    abstract edit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string): void
    abstract getMarkdown(target: MarkdownDocumentTarget): string

    getBindingsSnapshot() {
        return this.bindings
    }

    getActiveTarget(binding: MarkdownBindingKind) {
        return this.bindings[bindingSnapshotKey(binding)]
    }

    setActiveTarget(binding: MarkdownBindingKind, target: MarkdownDocumentTarget | null, discard = false) {
        const key = bindingSnapshotKey(binding)
        if (sameMarkdownTarget(this.bindings[key], target)) return

        this.bindings = { ...this.bindings, [key]: target }
        const detail: ActiveMarkdownDocumentChangedDetail = { binding, discard, target }
        this.dispatchEvent(new CustomEvent('activeDocumentChanged', { detail }))
    }

    clearBindings(discard = false) {
        for (const binding of ['board-card', 'list-card', 'list-action'] as const) this.setActiveTarget(binding, null, discard)
    }

    protected dispatchMarkdownReplaced(detail: MarkdownReplacedDetail) {
        this.dispatchEvent(new CustomEvent('markdownReplaced', { detail }))
    }
}

import type { DataService } from '../../services/data/data_service'
import type { CardType } from '../../data/data_types'
import { dialogService } from '../../services/dialog_service'
import {
    openFilesService,
    type CardOpenDocument,
    type OpenDocumentChangedDetail,
    type OpenFilesService,
} from '../../services/open_files_service'
import {
    MarkdownDataSourceBase,
    type MarkdownBindingKind,
    type MarkdownDocumentTarget,
} from './markdown_data_source'

export type CardBinding = Exclude<MarkdownBindingKind, 'list-action'>
type CardMarkdownOwner = EventTarget & Pick<DataService, 'getState'> & {
    cards: Pick<DataService['cards'],
        'toggleCardPolicy' | 'updateCardBody' | 'updateCardHeaderFields' | 'updateCardTitle' | 'updateCardType'>
}
type ListCardOwner = EventTarget & Pick<OpenFilesService, 'getSnapshot'>

export interface CardDocumentClosedDetail {
    binding: 'list-card'
    document: CardOpenDocument
}

function cardTarget(target: MarkdownDocumentTarget): asserts target is { document: CardOpenDocument } {
    if (target.document.kind !== 'card') throw new Error('Card Markdown source requires a card document')
}

function readCardMarkdown(target: MarkdownDocumentTarget) {
    cardTarget(target)
    return target.document.getDraft().content
}

function editCardMarkdown(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string) {
    if (binding === 'list-action') throw new Error('Card Markdown source cannot use list-action binding')
    cardTarget(target)
    target.document.updateDraft({ content: markdown }, binding)
}

/** Reads and writes card body Markdown through focused card operations. */
export class CardMarkdownDataSource extends MarkdownDataSourceBase {
    private listCardOwner: ListCardOwner | null = null
    private service: CardMarkdownOwner | null = null

    init(service: CardMarkdownOwner) {
        if (this.service) return

        this.service = service
        openFilesService.addEventListener('documentChanged', this.handleDocumentChanged)
    }

    dispose() {
        openFilesService.removeEventListener('documentChanged', this.handleDocumentChanged)
        this.setBoardDocument(null)
    }

    bindListCards(owner: ListCardOwner) {
        if (this.listCardOwner === owner) return
        if (this.listCardOwner) throw new Error('Card Markdown data source already has a list-card owner')

        this.listCardOwner = owner
        owner.addEventListener('changed', this.handleListCardsChanged)
        owner.addEventListener('removed', this.handleListCardRemoved)
        this.syncListCardBinding()
    }

    getActiveDocument(binding: CardBinding) {
        const target = this.getActiveTarget(binding)
        return target?.document.kind === 'card' ? target.document : null
    }

    getActiveCard(binding: CardBinding) {
        return this.getActiveDocument(binding)?.getObject() ?? null
    }

    getProjectKey() {
        const { project } = this.requireService().getState()
        if (!project) throw new Error('Cannot resolve a card project before a project is open')

        return `${project.id}:${project.branch}`
    }

    updateActiveCardTitle(binding: CardBinding, title: string) {
        const document = this.requireActiveDocument(binding)
        this.requireService().cards.updateCardTitle(document.path, title)
            .catch((error: unknown) => {
                dialogService.error(error, { fallbackMessage: `Title update failed: ${document.path}` })
            })
    }

    updateActiveCardType(binding: CardBinding, type: CardType) {
        const document = this.requireActiveDocument(binding)

        return this.requireService().cards.updateCardType(document.path, type)
            .catch((error: unknown) => {
                dialogService.error(error, { fallbackMessage: `Card type update failed: ${document.path}` })
            })
    }

    updateActiveCardHeaderField(binding: CardBinding, key: string, value: string) {
        const document = this.requireActiveDocument(binding)
        if (key !== 'author') throw new Error(`Unsupported editable card header field: ${key}`)

        this.requireService().cards.updateCardHeaderFields(document.path, { [key]: value })
    }

    toggleActiveCardPolicy(binding: CardBinding, policyKey: string) {
        const document = this.requireActiveDocument(binding)
        this.requireService().cards.toggleCardPolicy(document.path, policyKey)
    }

    readonly getMarkdown = readCardMarkdown
    readonly edit = editCardMarkdown

    commit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string) {
        CardMarkdownDataSource.requireCardBinding(binding)
        cardTarget(target)
        try {
            const draft = target.document.getDraft()
            if (draft.content !== markdown) target.document.updateDraft({ content: markdown }, binding)
            this.requireService().cards.updateCardBody(
                target.document.path,
                markdown,
                target.document.createSaveReference(),
            )
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Body update failed: ${target.document.path}` })
            return false
        }
    }

    setBoardDocument(document: CardOpenDocument | null, discard = false) {
        this.setActiveTarget('board-card', document ? { document } : null, discard)
    }

    private readonly handleDocumentChanged = (event: Event) => {
        const { document, origin, type } = (event as CustomEvent<OpenDocumentChangedDetail>).detail
        if (document.kind !== 'card') return

        if (type === 'renewed') {
            this.dispatchEvent(new Event('cardsChanged'))
            return
        }
        if (type !== 'draft') return

        const originBinding = typeof origin === 'string' ? origin as MarkdownBindingKind : null
        this.dispatchMarkdownReplaced({ originBinding, target: { document } })
    }

    private readonly handleListCardsChanged = () => this.syncListCardBinding()

    private readonly handleListCardRemoved = (event: Event) => {
        const { document } = (event as CustomEvent<{ document: ReturnType<ListCardOwner['getSnapshot']>['activeDocument'] }>).detail
        if (!document || document.kind !== 'card') return

        const detail: CardDocumentClosedDetail = { binding: 'list-card', document }
        this.dispatchEvent(new CustomEvent<CardDocumentClosedDetail>('cardDocumentClosed', { detail }))
    }

    private syncListCardBinding() {
        const activeDocument = this.listCardOwner?.getSnapshot().activeDocument ?? null
        this.setActiveTarget('list-card', activeDocument?.kind === 'card' ? { document: activeDocument } : null)
    }

    private requireActiveDocument(binding: CardBinding) {
        const document = this.getActiveDocument(binding)
        if (!document) throw new Error(`Cannot update a card without an active ${binding} document`)

        return document
    }

    private static requireCardBinding(binding: MarkdownBindingKind) {
        if (binding === 'list-action') throw new Error('Card Markdown source cannot use list-action binding')
    }

    private requireService() {
        if (!this.service) throw new Error('Card Markdown data source is not initialized')
        return this.service
    }
}

