import { computeMove, type CardMoveUpdate } from '../../data/card_ordering'
import type { CardDraft, CardType, MarkdownFile, Card } from '../../data/data_types'
import type { OpenDocumentSaveReference } from '../open_files_service'
import { telemetryService } from '../telemetry/telemetry_service'
import { CardArchiveOperations } from './card_archive_operations'
import { CardInternalIdOperations } from './card_internal_id_operations'
import {
    CardOperationContext,
    type CardOperationsDeps,
    type CommitRequest,
} from './card_operation_context'
import { CardRenameOperations } from './card_rename_operations'
import { ProjectFileOperations } from './project_file_operations'
import {
    clearCardBranch,
    setCardAffects,
    setCardAgentLogReferences,
    setCardBody,
    setCardHeaderFields,
    setCardWorktree,
    setCardWorktreeAssignment,
    toggleCardPolicy,
} from './card_mutations'

export type { CardOperationsDeps }

/** The card-facing surface of the data service, delegating to focused operation modules. */
export class CardOperations {
    private readonly context: CardOperationContext
    private readonly archives: CardArchiveOperations
    private readonly internalIds: CardInternalIdOperations
    private readonly projectFiles: ProjectFileOperations
    private readonly renames: CardRenameOperations
    private readonly triggerStateActions: (cardPath: string, state: string) => void

    constructor(
        dependencies: CardOperationsDeps,
        triggerStateActions: (cardPath: string, state: string) => void,
    ) {
        this.context = new CardOperationContext(dependencies)
        this.triggerStateActions = triggerStateActions
        this.archives = new CardArchiveOperations(this.context, triggerStateActions)
        this.renames = new CardRenameOperations(this.context)
        this.internalIds = new CardInternalIdOperations(this.context, () => this.renames.reset())
        this.projectFiles = new ProjectFileOperations(this.context)
    }

    async createCard(draft: CardDraft, initialState: string) {
        const { config, project } = this.context.requireProject('create a card')
        const { dependencies } = this.context

        const file = createCardFile(
            dependencies.files(),
            config.workingFolder,
            config.cardSeparator,
            config.cardTypes,
            config.cardBodyTemplate,
            initialState,
            draft,
        )
        dependencies.updateFiles([file], [], config.workingFolder)
        await this.context.commitCreatedFiles({
            branch: project.branch,
            files: [file],
            message: `Create ${file.path}`,
        })
        void this.context.pushCreatedItem('Card')

        telemetryService.trackEvent('create_card')

        return file
    }

    createFolder(parentDirectory: string, name: string) {
        return this.projectFiles.createFolder(parentDirectory, name)
    }

    createMarkdownFile(parentDirectory: string, name: string) {
        return this.projectFiles.createMarkdownFile(parentDirectory, name)
    }

    updateCardBody(path: string, body: string, saveReference?: OpenDocumentSaveReference) {
        return this.context.saveCardChange(path, (card) => setCardBody(card, body), saveReference)
    }

    updateCardAffects(path: string, affects: string[]): Card {
        return this.context.saveCardChange(path, (card) => setCardAffects(card, affects))
    }

    updateCardHeaderFields(path: string, updates: Record<string, string>, saveReference?: OpenDocumentSaveReference) {
        return this.context.saveCardChange(path, (card) => setCardHeaderFields(card, updates), saveReference)
    }

    updateCardWorktree(path: string, worktree: number | null) {
        return this.context.saveCardChange(path, (card) => setCardWorktree(card, worktree))
    }

    assignCardWorktree(path: string, worktree: number, branch: string) {
        return this.context.saveCardChange(path, (card) => setCardWorktreeAssignment(card, worktree, branch))
    }

    clearCardBranch(path: string) {
        return this.context.saveCardChange(path, clearCardBranch)
    }

    toggleCardPolicy(path: string, policyKey: string, saveReference?: OpenDocumentSaveReference): Card {
        return this.context.saveCardChange(path, (card) => toggleCardPolicy(card, policyKey), saveReference)
    }

    addAgentLogReference(path: string, reference: string) {
        const card = this.context.dependencies.requireCard(path)
        if (card.header.agentLogReferences.includes(reference)) return card.header.internalId

        const references = [...new Set([...card.header.agentLogReferences, reference])]
        this.context.saveCardChange(path, (currentCard) => setCardAgentLogReferences(currentCard, references))

        return card.header.internalId
    }

    setAgentLogReferences(path: string, references: string[], message = `Update ${path}`) {
        const card = this.context.dependencies.requireCard(path)
        const currentReferences = card.header.agentLogReferences
        const unchanged = currentReferences.length === references.length
            && currentReferences.every((reference, index) => reference === references[index])
        if (unchanged) return card

        return this.context.saveCardChange(
            path,
            (currentCard) => setCardAgentLogReferences(currentCard, references),
            undefined,
            message,
        )
    }

    ensureCardInternalIds() {
        return this.internalIds.ensureCardInternalIds()
    }

    updateCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {
        return this.renames.updateCardTitle(path, title, saveReference)
    }

    updateCardType(path: string, type: CardType, saveReference?: OpenDocumentSaveReference) {
        return this.renames.updateCardType(path, type, saveReference)
    }

    async moveCard(cardPath: string, targetStatus: string, targetIndex: number) {
        if (targetStatus === 'archived') return this.archives.archiveCard(cardPath, targetIndex)

        const activeCards = this.context.dependencies.snapshot()?.activeCards ?? []
        const movedCard = activeCards.find((card) => card.path === cardPath)
        const previousStatus = movedCard?.header.status ?? null
        const updates = computeMove(activeCards, cardPath, targetStatus, targetIndex)

        this.saveCardMoveUpdates(cardPath, updates)

        if (movedCard && previousStatus !== targetStatus) this.triggerStateActions(movedCard.path, targetStatus)

        return updates
    }

    /** Applies every ordering link from one move to local state and one persistence batch. */
    private saveCardMoveUpdates(cardPath: string, updates: CardMoveUpdate[]) {
        if (updates.length === 0) return

        const { commitBatcher, project } = this.context.requireProject('move a card')
        const updatedCards = this.context.applyOrderingUpdates(updates)
        const changes = updatedCards.map((card) => {
            const cardInternalId = card.header.internalId
            if (!cardInternalId) throw new Error(`Cannot move a card without an internal ID: ${card.path}`)

            return {
                cardInternalId,
                path: card.path,
                saveReference: this.context.findOpenCardDocument(card.path)?.createSaveReference(),
            }
        })
        commitBatcher.schedule(project.branch, changes, `Move ${cardPath}`)
        this.context.dependencies.dispatchPersistenceChanged()
    }
    }

    async deleteCard(path: string) {
        const card = this.context.dependencies.snapshot()?.activeCards.find((currentCard) => currentCard.path === path)
        if (!card) throw new Error(`Cannot delete an active card that is not loaded: ${path}`)

        return this.projectFiles.deleteProjectFile(path, true)
    }

    async deleteFile(path: string) {
        const { dependencies } = this.context
        const loadedFile = dependencies.files().some((file) => file.path === path)
        const repositoryFile = dependencies.snapshot()?.repositoryFiles.includes(path) ?? false
        if (!loadedFile && !repositoryFile) throw new Error(`Cannot delete a file that is not loaded: ${path}`)

        const activeCard = dependencies.snapshot()?.activeCards.some((card) => card.path === path) ?? false

        return this.projectFiles.deleteProjectFile(path, activeCard)
    }

    deleteFolder(path: string) {
        return this.projectFiles.deleteFolder(path)
    }

    saveFile(file: MarkdownFile, saveReference?: OpenDocumentSaveReference) {
        return this.context.saveFile(file, saveReference)
    }

    saveProjectFile(file: MarkdownFile, message: string) {
        return this.projectFiles.saveProjectFile(file, message)
    }

    flushPendingCommits() {
        return this.context.flushPendingCommits()
    }

    deferAutomaticCommit() {
        const { commitBatcher } = this.context.requireProject('defer automatic card commits')

        return commitBatcher.deferAutomaticFlush()
    }

    commitFiles(request: CommitRequest) {
        return this.context.commitFiles(request)
    }

    pushCommittedFiles(request: CommitRequest) {
        return this.context.pushCommittedFiles(request)
    }

    commitAndMergeFiles(request: CommitRequest, fallbackFiles: MarkdownFile[] = []) {
        return this.context.commitAndMergeFiles(request, fallbackFiles)
    }

    requireCardByInternalId(internalId: string) {
        return this.context.dependencies.requireCardByInternalId(internalId)
    }
}

import type { CardMoveUpdate } from '../../data/card_ordering'
import type { Card, MarkdownFile, MoveFile, ProjectReference, ProjectSnapshot, StorageService } from '../../data/data_types'
import type { CardOpenDocument, OpenDocumentSaveReference } from '../open_files_service'
import { openFilesService } from '../open_files_service'
import { telemetryService } from '../telemetry/telemetry_service'
import { projectAccessService } from '../project/project_access_service'
import {
    errorMessage,
    type RequiredDataServiceDependencies,
    reportCommitFlushFailure,
    reportWorkspaceError,
} from './data_service_context'
import { setCardHeaderFields } from './card_mutations'

export type CommitRequest = Parameters<StorageService['commit']>[0]
type PendingCommitFile = MarkdownFile & { saveReference?: OpenDocumentSaveReference }

export interface CardOperationsDeps {
    addRepositoryFile(path: string): void
    applyMoves(moves: MoveFile[], workingFolder: string): void
    cardPathChanged(fromPath: string, toPath: string): void
    commitPathsInFlight(): Set<string>
    deleteFile(path: string, committedFiles: MarkdownFile[], workingFolder: string): void
    dispatchChanged(): void
    dispatchPersistenceChanged(): void
    files(): MarkdownFile[]
    mergeCommittedFiles(files: MarkdownFile[], workingFolder: string): void
    mutateCard(path: string, mutation: (card: Card) => void, workingFolder: string): Card
    project(): ProjectReference | null
    recordCurrentContent(files: MarkdownFile[]): void
    refreshSnapshot(workingFolder: string): void
    reloadCurrentProjectSnapshot(): Promise<ProjectSnapshot | null>
    removeFolder(path: string, workingFolder: string): void
    renameFile(fromPath: string, toPath: string, workingFolder: string): void
    requireDependencies(): RequiredDataServiceDependencies
    requireCard(path: string): Card
    requireCardByInternalId(internalId: string): Card
    requireFile(path: string): MarkdownFile
    replaceFiles(files: MarkdownFile[], workingFolder: string): void
    snapshot(): ProjectSnapshot | null
    updateFiles(updatedFiles: MarkdownFile[], removedPaths: string[], workingFolder: string): void
}

/** The dependencies every card operation resolves once it knows a project is open. */
export interface OpenProjectDependencies extends RequiredDataServiceDependencies {
    project: ProjectReference
}

function attachSaveReference(file: MarkdownFile, saveReference: OpenDocumentSaveReference | undefined): PendingCommitFile {
    return saveReference ? { ...file, saveReference } : file
}

/**
 * Shared state and primitives every card operation module builds on: project lookup,
 * snapshot indexing, open-document synchronization, local file replacement and commits.
 */
export class CardOperationContext {
    readonly dependencies: CardOperationsDeps
    /** Path index per snapshot instance so repeated card lookups do not rescan both card lists. */
    private readonly cardsBySnapshot = new WeakMap<ProjectSnapshot, Map<string, Card>>()

    constructor(dependencies: CardOperationsDeps) {
        this.dependencies = dependencies
    }

    /** Resolves the storage dependencies plus the open project, or throws `Cannot <action> before a project is open`. */
    requireProject(action: string): OpenProjectDependencies {
        projectAccessService.requireWritable()
        const { commitBatcher, config, storage } = this.dependencies.requireDependencies()
        const project = this.dependencies.project()
        if (!project) throw new Error(`Cannot ${action} before a project is open`)

        return { commitBatcher, config, project, storage }
    }

    findCard(path: string): Card | null {
        const snapshot = this.dependencies.snapshot()
        if (!snapshot) return null

        let cardsByPath = this.cardsBySnapshot.get(snapshot)
        if (!cardsByPath) {
            cardsByPath = new Map([...snapshot.activeCards, ...snapshot.backgroundCards].map((card) => [card.path, card]))
            this.cardsBySnapshot.set(snapshot, cardsByPath)
        }

        return cardsByPath.get(path) ?? null
    }

    findOpenCardDocument(path: string): CardOpenDocument | null {
        const card = this.findCard(path)
        const document = card ? openFilesService.findDocument(card) : null

        return document?.kind === 'card' ? document : null
    }

    /** Overlays updated files onto the loaded files by path, leaving every other file untouched. */
    mergeUpdatedFiles(updatedFiles: MarkdownFile[]): MarkdownFile[] {
        const updatedFilesByPath = new Map(updatedFiles.map((file) => [file.path, file]))

        return this.dependencies.files().map((file) => updatedFilesByPath.get(file.path) ?? file)
    }

    replaceUpdatedFiles(updatedFiles: MarkdownFile[]) {
        const { config } = this.dependencies.requireDependencies()
        this.dependencies.replaceFiles(this.mergeUpdatedFiles(updatedFiles), config.workingFolder)
    }

    /** Applies a focused card mutation while carrying any unsaved editor body into owned state. */
    mutateCardPreservingOpenBody(path: string, mutation: (card: Card) => void, workingFolder: string) {
        const openDocument = this.findOpenCardDocument(path)
        const dirtyBody = openDocument?.dirty ? openDocument.getDraft().content : null

        return this.dependencies.mutateCard(path, (ownedCard) => {
            if (dirtyBody !== null) ownedCard.content = dirtyBody
            mutation(ownedCard)
        }, workingFolder)
    }

    /** Mutates the `after`/`status` fields for every ordering link produced by a move. */
    applyOrderingUpdates(updates: CardMoveUpdate[]): Card[] {
        const { config } = this.dependencies.requireDependencies()

        return updates.map((update) => {
            return this.dependencies.mutateCard(update.path, (card) => setCardHeaderFields(card, {
                after: update.after ?? '',
                status: update.status,
            }), config.workingFolder)
        })
    }

    /** Commits while every touched path is marked in flight so snapshot reloads skip them. */
    async commitTrackingPaths(request: CommitRequest): Promise<MarkdownFile[]> {
        const { storage } = this.dependencies.requireDependencies()
        const commitPaths = [
            ...request.files.map((file) => file.path),
            ...(request.moves ?? []).flatMap(({ fromPath, toPath }) => [fromPath, toPath]),
        ]
        const inFlightCommitPaths = this.dependencies.commitPathsInFlight()
        commitPaths.forEach((path) => inFlightCommitPaths.add(path))

        try {
            const committedFiles = await storage.commit(request)
            this.dependencies.recordCurrentContent(request.files)

            return committedFiles
        } finally {
            commitPaths.forEach((path) => inFlightCommitPaths.delete(path))
        }
    }

    /** Commits and merges the result into local state. */
    async commitFiles(request: CommitRequest) {
        const { config } = this.dependencies.requireDependencies()
        const updatedFiles = await this.commitTrackingPaths(request)
        const loadedPaths = new Set(this.dependencies.files().map(({ path }) => path))
        const fallbackFiles = request.files.filter(({ path }) => loadedPaths.has(path))
        const committedFiles = updatedFiles.length > 0 ? updatedFiles : fallbackFiles

        if (committedFiles.length > 0) {
            this.dependencies.mergeCommittedFiles(committedFiles, config.workingFolder)
            this.dependencies.refreshSnapshot(config.workingFolder)
        }

        if (config.pushMode === 'manual') this.dependencies.dispatchPersistenceChanged()

        return updatedFiles
    }

    /** Pushes a successfully persisted batch without delaying local save acknowledgement. */
    async pushCommittedFiles(request: CommitRequest) {
        const { config, storage } = this.dependencies.requireDependencies()
        if (config.pushMode !== 'auto') return

        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot push committed files before a project is open')
        if (currentProject.branch !== request.branch) throw new Error(`Cannot push committed files for inactive branch: ${request.branch}`)

        await storage.push(currentProject)
        this.dependencies.dispatchPersistenceChanged()
    }

    /** Commits and merges, falling back to the requested files when storage returns nothing. */
    async commitAndMergeFiles(request: CommitRequest, fallbackFiles: MarkdownFile[] = []) {
        const { config } = this.dependencies.requireDependencies()
        const updatedFiles = await this.commitTrackingPaths(request)
        const committedFiles = updatedFiles.length > 0 ? updatedFiles : fallbackFiles
        if (committedFiles.length === 0) return updatedFiles

        this.dependencies.mergeCommittedFiles(committedFiles, config.workingFolder)
        this.dependencies.refreshSnapshot(config.workingFolder)

        return updatedFiles
    }

    /** Commits newly inserted files and applies only persistence metadata returned by storage. */
    async commitCreatedFiles(request: CommitRequest) {
        const { config } = this.dependencies.requireDependencies()
        const updatedFiles = await this.commitTrackingPaths(request)
        if (updatedFiles.length > 0) this.dependencies.updateFiles(updatedFiles, [], config.workingFolder)

        return updatedFiles
    }

    /** Queues a local file change for the batched commit, keeping the open document in sync. */
    saveFile(file: MarkdownFile, saveReference?: OpenDocumentSaveReference) {
        const { commitBatcher, project } = this.requireProject('save a file')
        const existingFile = this.dependencies.requireFile(file.path)
        if (existingFile.content === file.content) return existingFile

        this.replaceUpdatedFiles([file])
        commitBatcher.schedule(project.branch, [attachSaveReference(file, saveReference)], `Update ${file.path}`)
        this.dependencies.dispatchChanged()

        return file
    }

    /** Mutates one owned card and queues its reference for serialization at flush. */
    saveCardChange(
        path: string,
        mutation: (card: Card) => void,
        saveReference?: OpenDocumentSaveReference,
        message = `Update ${path}`,
    ) {
        const { commitBatcher, config, project } = this.requireProject('save a card')
        const openDocument = this.findOpenCardDocument(path)
        const card = this.mutateCardPreservingOpenBody(path, mutation, config.workingFolder)
        const cardInternalId = card.header.internalId
        if (!cardInternalId) throw new Error(`Cannot save a card without an internal ID: ${path}`)
        const documentSaveReference = saveReference ?? openDocument?.createSaveReference()

        commitBatcher.schedule(project.branch, [{ cardInternalId, path: card.path, saveReference: documentSaveReference }], message)
        this.dependencies.dispatchChanged()

        return card
    }

    async flushPendingCommits() {
        const { commitBatcher } = this.dependencies.requireDependencies()
        const hadPendingCommits = commitBatcher.hasPending()

        try {
            await commitBatcher.flush()
        } catch (error) {
            reportCommitFlushFailure(error, this.dependencies.dispatchPersistenceChanged)
            throw error
        }

        if (hadPendingCommits) this.dependencies.dispatchPersistenceChanged()
    }

    /** Pushes a freshly created item when auto push is on, reporting failures without failing the creation. */
    async pushCreatedItem(createdItem: string) {
        const { config, project, storage } = this.requireProject('push')
        if (config.pushMode !== 'auto') return

        try {
            await storage.push(project)
        } catch (error) {
            const detail = errorMessage(error, 'GitHub push failed')
            reportWorkspaceError(
                `${createdItem} created locally, but GitHub push failed. Use Push after resolving the GitHub access problem. ${detail}`,
            )
            telemetryService.captureError(error)
        }
    }

    /** Rejects a new project item path that an existing file or folder already occupies. */
    requireAvailablePath(path: string) {
        const snapshot = this.dependencies.snapshot()
        if (!snapshot) throw new Error('Cannot create a project item before project files are loaded')

        const normalizedPath = path.toLowerCase()
        const existingPaths = [
            ...this.dependencies.files().map((file) => file.path),
            ...snapshot.repositoryFiles,
        ].map((existingPath) => existingPath.replace(/\\/gu, '/').toLowerCase())
        const pathExists = existingPaths.some((existingPath) => (
            existingPath === normalizedPath
            || existingPath.startsWith(`${normalizedPath}/`)
        ))
        if (pathExists) throw new Error(`A project item already exists at ${path}`)
    }
}

export { attachSaveReference }

import { orderByAfter, statusOf } from '../../data/card_ordering'
import type { MarkdownFile } from '../../data/data_types'
import { newFolderPath, newMarkdownFilePath } from '../../data/project_tree_paths'
import type { CardOperationContext } from './card_operation_context'
import { markdownParsingService } from './markdown_parsing_service'
import { setCardHeaderFields } from './card_mutations'

const FOLDER_PLACEHOLDER_NAME = '.gitkeep'

/** Creating, saving and deleting plain project files and folders outside the card workflow. */
export class ProjectFileOperations {
    private readonly context: CardOperationContext

    constructor(context: CardOperationContext) {
        this.context = context
    }

    async createFolder(parentDirectory: string, name: string) {
        const { config, project, storage } = this.context.requireProject('create a folder')

        const folderPath = newFolderPath(parentDirectory, name, config.projectFolder)
        this.context.requireAvailablePath(folderPath)
        await storage.commit({
            branch: project.branch,
            files: [{ content: '', path: `${folderPath}/${FOLDER_PLACEHOLDER_NAME}` }],
            message: `Create ${folderPath}`,
        })
        await this.context.pushCreatedItem('Folder')
        this.context.dependencies.addRepositoryFile(`${folderPath}/${FOLDER_PLACEHOLDER_NAME}`)
        this.context.dependencies.dispatchChanged()

        return folderPath
    }

    async createMarkdownFile(parentDirectory: string, name: string) {
        const { config, project } = this.context.requireProject('create a Markdown file')

        const path = newMarkdownFilePath(parentDirectory, name, config.projectFolder)
        this.context.requireAvailablePath(path)
        const file = { content: '', path }
        await this.context.commitAndMergeFiles({
            branch: project.branch,
            files: [file],
            message: `Create ${path}`,
        }, [file])
        await this.context.pushCreatedItem('Markdown file')

        return file
    }

    async saveProjectFile(file: MarkdownFile, message: string) {
        const { config, project, storage } = this.context.requireProject('save a project file')

        await this.context.commitAndMergeFiles({ branch: project.branch, files: [file], message }, [file])

        if (config.pushMode === 'auto') await storage.push(project)

        return file
    }

    async deleteFolder(path: string) {
        const { config, project, storage } = this.context.requireProject('delete a folder')

        const folderPrefix = `${path.replace(/\/+$/u, '')}/`
        const repositoryFiles = this.context.dependencies.snapshot()?.repositoryFiles ?? []
        if (!repositoryFiles.some((filePath) => filePath.startsWith(folderPrefix))) {
            throw new Error(`Cannot delete a folder that is not loaded: ${path}`)
        }

        await this.context.flushPendingCommits()
        await storage.deleteFolder({ branch: project.branch, message: `Delete ${path}`, path })
        if (config.pushMode === 'auto') await storage.push(project)
        this.context.dependencies.removeFolder(path, config.workingFolder)
        this.context.dependencies.dispatchChanged()

        return this.context.dependencies.snapshot()
    }

    /** Deletes a file, first repairing the `after` chain when an ordered active card leaves the board. */
    async deleteProjectFile(path: string, repairActiveOrdering: boolean) {
        const { dependencies } = this.context
        const { config, project, storage } = this.context.requireProject('delete a file')

        await this.context.flushPendingCommits()

        const existingFile = dependencies.files().find((file) => file.path === path)
        const repairFile = repairActiveOrdering ? this.createDeleteRepairFile(path) : null
        let committedRepairFiles: MarkdownFile[] = []

        if (repairFile) {
            committedRepairFiles = await storage.commit({
                branch: project.branch,
                files: [repairFile],
                message: `Repair ordering after deleting ${path}`,
            })
        }

        await storage.deleteFile({
            branch: project.branch,
            message: `Delete ${path}`,
            path,
            ...(existingFile?.sha ? { sha: existingFile.sha } : {}),
        })

        if (config.pushMode === 'auto') await storage.push(project)

        if (repairFile && committedRepairFiles.length === 0) committedRepairFiles = [repairFile]
        dependencies.deleteFile(path, committedRepairFiles, config.workingFolder)
        dependencies.dispatchChanged()

        return dependencies.snapshot()
    }

    /** Relinks the follower of a deleted card onto the deleted card's predecessor. */
    private createDeleteRepairFile(path: string): MarkdownFile | null {
        const activeCards = this.context.dependencies.snapshot()?.activeCards ?? []
        const deletedCard = activeCards.find((card) => card.path === path)
        if (!deletedCard?.header.internalId) return null

        const column = orderByAfter(activeCards.filter((card) => statusOf(card) === statusOf(deletedCard)))
        const deletedIndex = column.findIndex((card) => card.path === path)
        const follower = column[deletedIndex + 1]
        if (!follower || follower.header.after !== deletedCard.header.internalId) return null

        const { config } = this.context.dependencies.requireDependencies()
        const followerCard = this.context.dependencies.mutateCard(
            follower.path,
            (card) => setCardHeaderFields(card, { after: deletedCard.header.after ?? '' }),
            config.workingFolder,
        )

        return markdownParsingService.serializeCard(followerCard)
    }
}

